function epsTarray = passler_epsTarray_generator(w,mats,euler,doping)
    % new version: 15.08.2019, alex 
    % generates the epsilon tensor array for transfer matrix calculations
    % need for passler_transfer_matrix_modular_k
    % input arguments: 
    %   w:      incoming frequency (1/cm)           
    %                                       1d-array of doubles
    %   mats:   material names in the layer stack   
    %                                       cell array of strings
    %                   need to match material names defined below
    %   euler:  euler angles for crystal frame rotation  
    %                                       cell array of double arrays 
    %                                       (rotation about z,x,z')
    %   doping: plasma frequency and damping for drude contribution
    %                                       cell array of double arrays
    %                                        (wp,Gp)
    % output 
    %   epsTarray: epsilon tensor array 
    %                                       cell array of 3x3xNw matrices
    debug = 0;
    Nds = length(mats);
    Nw = length(w);
    %%%%%%%%%%%%%%%%%%%%
    % material database, hard coded
    %%%%%%%%%%%%%%%%%%%%
    epsTarray = cell(Nds,1);
  
    % single phonon mode oscillator model parameters
    wlAlN     = 909.6;
    wtAlN     = 667.2;
    GtAlN     = 2.2;
    epsinfAlN = 4.160;
    wlAlNz     = 888.9;
    wtAlNz     = 608.5;
    GtAlNz     = 2.2;
    epsinfAlNz = 4.350;

    % Caldwell
    wlhBN      = 1616.9;
    wthBN      = 1362.7;
    GthBN      = 7.3;
    epsinfhBN  = 4.98;
    wlhBNz      = 825;
    wthBNz      = 760;
    GthBNz      = 3;
    epsinfhBNz  = 2.95;    

    % original
    % wlhBN      = 1614;
    % wthBN      = 1360;
    % GthBN      = 7;
    % epsinfhBN  = 4.9;
    % wlhBNz      = 811;
    % wthBNz      = 760;
    % GthBNz      = 1;
    % epsinfhBNz  = 2.95; 

    wlInN       = 593;
    wtInN       = 476;
    GtInN       = 4.4;
    epsinfInN   = 8.45;
    wlInNz      = 586;
    wtInNz      = 447;
    GtInNz       = 4.4;
    epsinfInNz  = 8.35;
    
    wtNEWmatx   = 200;
    sNEWmatx    = 10;
    gNEWmatx    = .05;
    epsinfNEWmatx = 10;
    
    wtMoO3x     = 821;
    wlMoO3x     = 963;
    GMoO3x      = 5.8;
    epsinfMoO3x = 4.0;
    wtMoO3y     = 544.6;
    wlMoO3y     = 850.1;
    GMoO3y      = 9.5;
    epsinfMoO3y = 6;
    wtMoO3z     = 956.7;
    wlMoO3z     = 1006.9;
    GMoO3z      = 1.5;    
    epsinfMoO3z = 4.5;
        
    % Lorentz-oscillator model
    eps  = @(w,wT,wL,gT,epsinf)epsinf*(w.^2-wL^2+1i*gT*w)./(w.^2-wT^2+1i*gT*w);
    epsTobi= @(w,wTO,S,gamma,epsinf)epsinf+(wTO.^2.*S)./(wTO.^2-w.^2-1i*gamma.*w*wTO);

    
    eps_NEWmatx= @(w)epsTobi(w,wtNEWmatx,sNEWmatx,gNEWmatx,epsinfNEWmatx);           % arbitrary material x
    
    % eps_MoO3x = @(w)eps(w,wtMoO3x,wlMoO3x,GMoO3x,epsinfMoO3x);
    % eps_MoO3y = @(w)eps(w,wtMoO3y,wlMoO3y,GMoO3y,epsinfMoO3y);
    % eps_MoO3z = @(w)eps(w,wtMoO3z,wlMoO3z,GMoO3z,epsinfMoO3z);

    % eps_18O_MoO3x = @(w)eps(w,wt18O_MoO3x,wl18O_MoO3x,GMoO3x,epsinfMoO3x);
    % eps_18O_MoO3y = @(w)eps(w,wt18O_MoO3y,wl18O_MoO3y,GMoO3y,epsinfMoO3y);
    % eps_18O_MoO3z = @(w)eps(w,wt18O_MoO3z,wl18O_MoO3z,GMoO3z,epsinfMoO3z);
    % eps_18O_MoO3x = @(w)eps(w,wt18O_thzMoO3x,wl18O_thzMoO3x,GMoO3x,epsinfMoO3x);
    % eps_18O_MoO3y = @(w)eps(w,wt18O_thzMoO3y,wl18O_thzMoO3y,GMoO3y,epsinfMoO3y);
    % eps_18O_MoO3z = @(w)eps(w,wt18O_thzMoO3z,wl18O_thzMoO3z,GMoO3z,epsinfMoO3z);
    % 
    % eps_98Mo_MoO3x = @(w)eps(w,wt98Mo_MoO3x,wl98Mo_MoO3x,GMoO3x,epsinfMoO3x);
    % eps_98Mo_MoO3y = @(w)eps(w,wt98Mo_MoO3y,wl98Mo_MoO3y,GMoO3y,epsinfMoO3y);
    % eps_98Mo_MoO3z = @(w)eps(w,wt98Mo_MoO3z,wl98Mo_MoO3z,GMoO3z,epsinfMoO3z);

    eps_AlN  =  @(w)eps(w,wtAlN,wlAlN,GtAlN,epsinfAlN);
    eps_AlNz =  @(w)eps(w,wtAlNz,wlAlNz,GtAlNz,epsinfAlNz);

    eps_InN  =  @(w)eps(w,wtInN,wlInN,GtInN,epsinfInN);
    eps_InNz =  @(w)eps(w,wtInNz,wlInNz,GtInNz,epsinfInNz);

    eps_hBN  =  @(w)eps(w,wthBN,wlhBN,GthBN,epsinfhBN);
    eps_hBNz =  @(w)eps(w,wthBNz,wlhBNz,GthBNz,epsinfhBNz);
    
    zeros_w   = @(w)zeros(size(w,1),size(w,2));
    ones_w    = @(w)ones(size(w,1),size(w,2));

    % constant epsilon materials
    eps_Si      =  @(w)13*ones_w(w);
    eps_Ge      =  @(w)16*ones_w(w);
    eps_Diamond  = @(w)5.6539.*ones_w(w);
    eps_NEWmaty=@(w)10*ones_w(w);               % arbitrary material y
    eps_NEWmatz=@(w)10*ones_w(w);               % arbitrary material z
    
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    % build tensors
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    % air/vacuum
    epsT_vac = zeros(3,3,Nw);
    epsT_vac(1,:,:) = [ones_w(w);zeros_w(w);zeros_w(w);];      
    epsT_vac(2,:,:) = [zeros_w(w);ones_w(w);zeros_w(w);];      
    epsT_vac(3,:,:) = [zeros_w(w);zeros_w(w);ones_w(w);];
    % Newsub
    epsT_Newsub = zeros(3,3,Nw);
    newsub = ones_w(w) * 10 + 0.001i;
    epsT_Newsub(1,:,:) = [newsub;zeros_w(w);zeros_w(w);];      
    epsT_Newsub(2,:,:) = [zeros_w(w);newsub;zeros_w(w);];      
    epsT_Newsub(3,:,:) = [zeros_w(w);zeros_w(w);newsub;];
    % Newmat
    epsT_Newmat = zeros(3,3,Nw);
    newmat = ones_w(w) * (-6) + 0.02i;
    epsT_Newmat(1,:,:) = [newmat;zeros_w(w);zeros_w(w);];      
    epsT_Newmat(2,:,:) = [zeros_w(w);newmat;zeros_w(w);];      
    epsT_Newmat(3,:,:) = [zeros_w(w);zeros_w(w);newmat;];
    % AlN
    epsT_AlN = zeros(3,3,Nw);
    epsT_AlN(1,:,:) = [eps_AlN(w);zeros_w(w);zeros_w(w);]; 
    epsT_AlN(2,:,:) = [zeros_w(w);eps_AlN(w);zeros_w(w);]; 
    epsT_AlN(3,:,:) = [zeros_w(w);zeros_w(w);eps_AlNz(w);];
    % GaN
    epsT_GaN = zeros(3,3,Nw);
    epsT_GaN(1,:,:) = [eps_GaNx(w);zeros_w(w);zeros_w(w);]; 
    epsT_GaN(2,:,:) = [zeros_w(w);eps_GaNx(w);zeros_w(w);]; 
    epsT_GaN(3,:,:) = [zeros_w(w);zeros_w(w);eps_GaNz(w);];
    % InN
    epsT_InN = zeros(3,3,Nw);
    epsT_InN(1,:,:) = [eps_InN(w);zeros_w(w);zeros_w(w);]; 
    epsT_InN(2,:,:) = [zeros_w(w);eps_InN(w);zeros_w(w);]; 
    epsT_InN(3,:,:) = [zeros_w(w);zeros_w(w);eps_InNz(w);];
    % hBN
    epsT_hBN = zeros(3,3,Nw);
    epsT_hBN(1,:,:) = [eps_hBN(w);zeros_w(w);zeros_w(w);]; 
    epsT_hBN(2,:,:) = [zeros_w(w);eps_hBN(w);zeros_w(w);]; 
    epsT_hBN(3,:,:) = [zeros_w(w);zeros_w(w);eps_hBNz(w);];
    % KRS5
    epsT_KRS5 = zeros(3,3,Nw);
    epsT_KRS5(1,:,:) = [eps_KRS5(w);zeros_w(w);zeros_w(w);]; 
    epsT_KRS5(2,:,:) = [zeros_w(w);eps_KRS5(w);zeros_w(w);]; 
    epsT_KRS5(3,:,:) = [zeros_w(w);zeros_w(w);eps_KRS5(w);];
    % Gold
    epsT_Au = zeros(3,3,Nw);
    epsT_Au(1,:,:) = [eps_Au(w);zeros_w(w);zeros_w(w);]; 
    epsT_Au(2,:,:) = [zeros_w(w);eps_Au(w);zeros_w(w);]; 
    epsT_Au(3,:,:) = [zeros_w(w);zeros_w(w);eps_Au(w);];
    % Gold effective
    epsT_Au_eff = zeros(3,3,Nw);
    epsT_Au_eff(1,:,:) = [eps_Au_eff(w);zeros_w(w);zeros_w(w);]; 
    epsT_Au_eff(2,:,:) = [zeros_w(w);eps_Au_eff(w);zeros_w(w);]; 
    epsT_Au_eff(3,:,:) = [zeros_w(w);zeros_w(w);eps_Au_eff(w);];
    % Metaplasmonics A
    epsT_MetaAuA = zeros(3,3,Nw);
    epsT_MetaAuA(1,:,:) = [eps_MetaAuA(w);zeros_w(w);zeros_w(w);]; 
    epsT_MetaAuA(2,:,:) = [zeros_w(w);eps_MetaAuA(w);zeros_w(w);]; 
    epsT_MetaAuA(3,:,:) = [zeros_w(w);zeros_w(w);eps_MetaAuB(w);];
    % Metaplasmonics B
    epsT_MetaAuB = zeros(3,3,Nw);
    epsT_MetaAuB(1,:,:) = [eps_MetaAuB(w);zeros_w(w);zeros_w(w);]; 
    epsT_MetaAuB(2,:,:) = [zeros_w(w);eps_MetaAuB(w);zeros_w(w);]; 
    epsT_MetaAuB(3,:,:) = [zeros_w(w);zeros_w(w);eps_MetaAuB(w);];
    % Metaplasmonics C
    epsT_MetaAuC = zeros(3,3,Nw);
    epsT_MetaAuC(1,:,:) = [eps_MetaAuC(w,'X');zeros_w(w);zeros_w(w);]; 
    epsT_MetaAuC(2,:,:) = [zeros_w(w);eps_MetaAuC(w,'Y');zeros_w(w);]; 
    epsT_MetaAuC(3,:,:) = [zeros_w(w);zeros_w(w);eps_MetaAuB(w);];
    % Metaplasmonics D
    epsT_MetaAuD = zeros(3,3,Nw);
    epsT_MetaAuD(1,:,:) = [eps_MetaAuD(w,'X');zeros_w(w);zeros_w(w);]; 
    epsT_MetaAuD(2,:,:) = [zeros_w(w);eps_MetaAuD(w,'Y');zeros_w(w);]; 
    epsT_MetaAuD(3,:,:) = [zeros_w(w);zeros_w(w);eps_MetaAuB(w);];
    % Metaplasmonics Pattern 4
    epsT_MetaP4 = zeros(3,3,Nw);
    epsT_MetaP4(1,:,:) = [eps_MetaP4(w,'X');zeros_w(w);zeros_w(w);]; 
    epsT_MetaP4(2,:,:) = [zeros_w(w);eps_MetaP4(w,'Y');zeros_w(w);]; 
    epsT_MetaP4(3,:,:) = [zeros_w(w);zeros_w(w);eps_MetaP4(w,'Z1');];
    % Metaplasmonics Pattern 5
    epsT_MetaP5 = zeros(3,3,Nw);
    epsT_MetaP5(1,:,:) = [eps_MetaP5(w,'X');zeros_w(w);zeros_w(w);]; 
    epsT_MetaP5(2,:,:) = [zeros_w(w);eps_MetaP5(w,'Y');zeros_w(w);]; 
    epsT_MetaP5(3,:,:) = [zeros_w(w);zeros_w(w);eps_MetaP5(w,'Z1');];
    % Silver
%     epsT_Ag = zeros(3,3,Nw);
%     epsT_Ag(1,:,:) = [eps_Ag(w);zeros_w(w);zeros_w(w);]; 
%     epsT_Ag(2,:,:) = [zeros_w(w);eps_Ag(w);zeros_w(w);]; 
%     epsT_Ag(3,:,:) = [zeros_w(w);zeros_w(w);eps_Ag(w);];
    % Silicon
    epsT_Si = zeros(3,3,Nw);
    epsT_Si(1,:,:) = [eps_Si(w);zeros_w(w);zeros_w(w);]; 
    epsT_Si(2,:,:) = [zeros_w(w);eps_Si(w);zeros_w(w);]; 
    epsT_Si(3,:,:) = [zeros_w(w);zeros_w(w);eps_Si(w);];
    % HRFZSilicon
    epsT_SiHRFZ = zeros(3,3,Nw);
    epsT_SiHRFZ(1,:,:) = [epsHRFZSi(w);zeros_w(w);zeros_w(w);]; 
    epsT_SiHRFZ(2,:,:) = [zeros_w(w);epsHRFZSi(w);zeros_w(w);]; 
    epsT_SiHRFZ(3,:,:) = [zeros_w(w);zeros_w(w);epsHRFZSi(w);];
    % effective substrate
    epsT_effSub = zeros(3,3,Nw);
    tgap = 30000; 
    L = 57000/pi;
    eps_effSub = (sqrt(eps_SiO2_IR_Full(w)) * tgap / L + sqrt(epsHRFZSi(w)) * (L - tgap) / L).^2;
    epsT_effSub(1,:,:) = [eps_effSub;zeros_w(w);zeros_w(w);]; 
    epsT_effSub(2,:,:) = [zeros_w(w);eps_effSub;zeros_w(w);]; 
    epsT_effSub(3,:,:) = [zeros_w(w);zeros_w(w);eps_effSub;];
    % Germanium
    epsT_Ge = zeros(3,3,Nw);
    epsT_Ge(1,:,:) = [eps_Ge_THz(w);zeros_w(w);zeros_w(w);]; 
    epsT_Ge(2,:,:) = [zeros_w(w);eps_Ge_THz(w);zeros_w(w);]; 
    epsT_Ge(3,:,:) = [zeros_w(w);zeros_w(w);eps_Ge_THz(w);];
    % Diamond
    epsT_Diamond = zeros(3,3,Nw);
    epsT_Diamond(1,:,:) = [eps_Diamond(w);zeros_w(w);zeros_w(w);]; 
    epsT_Diamond(2,:,:) = [zeros_w(w);eps_Diamond(w);zeros_w(w);]; 
    epsT_Diamond(3,:,:) = [zeros_w(w);zeros_w(w);eps_Diamond(w);];    
    % alpha-Quartz
    epsT_SiO2 = zeros(3,3,Nw);
    epsT_SiO2(1,:,:) = [eps_SiO2x(w);zeros_w(w);zeros_w(w);]; 
    epsT_SiO2(2,:,:) = [zeros_w(w);eps_SiO2x(w);zeros_w(w);]; 
    epsT_SiO2(3,:,:) = [zeros_w(w);zeros_w(w);eps_SiO2z(w);];
    % Alumina
    epsT_Al2O3 = zeros(3,3,Nw);
    epsT_Al2O3(1,:,:) = [eps_Al2O3o(w);zeros_w(w);zeros_w(w);]; 
    epsT_Al2O3(2,:,:) = [zeros_w(w);eps_Al2O3o(w);zeros_w(w);];
    epsT_Al2O3(3,:,:) = [zeros_w(w);zeros_w(w);eps_Al2O3e(w);]; 
    % Bariumtitanate
    epsT_BaTiO3 = zeros(3,3,Nw);
    epsT_BaTiO3(1,:,:) = [eps_BaTiO3(w);zeros_w(w);zeros_w(w);]; 
    epsT_BaTiO3(2,:,:) = [zeros_w(w);eps_BaTiO3(w);zeros_w(w);]; 
    epsT_BaTiO3(3,:,:) = [zeros_w(w);zeros_w(w);eps_BaTiO3(w);];     
    % BaF2
    epsT_BaF2 = zeros(3,3,Nw);
    epsT_BaF2(1,:,:) = [eps_BaF2(w);zeros_w(w);zeros_w(w);]; 
    epsT_BaF2(2,:,:) = [zeros_w(w);eps_BaF2(w);zeros_w(w);]; 
    epsT_BaF2(3,:,:) = [zeros_w(w);zeros_w(w);eps_BaF2(w);];
    % BaF2
    epsT_CaF2 = zeros(3,3,Nw);
    epsT_CaF2(1,:,:) = [eps_CaF2(w);zeros_w(w);zeros_w(w);]; 
    epsT_CaF2(2,:,:) = [zeros_w(w);eps_CaF2(w);zeros_w(w);]; 
    epsT_CaF2(3,:,:) = [zeros_w(w);zeros_w(w);eps_CaF2(w);];
    % STO
    epsT_STO = zeros(3,3,Nw);
    epsT_STO(1,:,:) = [eps_STO_Tony(w);zeros_w(w);zeros_w(w);]; 
    epsT_STO(2,:,:) = [zeros_w(w);eps_STO_Tony(w);zeros_w(w);]; 
    epsT_STO(3,:,:) = [zeros_w(w);zeros_w(w);eps_STO_Tony(w);];
%     % MoO3
%     epsT_MoO3 = zeros(3,3,Nw);
%     epsT_MoO3(1,:,:) = [eps_MoO3x(w);zeros_w(w);zeros_w(w);]; 
%     epsT_MoO3(2,:,:) = [zeros_w(w);eps_MoO3y(w);zeros_w(w);]; 
%     epsT_MoO3(3,:,:) = [zeros_w(w);zeros_w(w);eps_MoO3z(w);];
    % BNNT
    epsT_BNNT = zeros(3,3,Nw);
    partial = 0;
    epsT_BNNT(1,:,:) = [eps_BNNT(w,'ip',partial);zeros_w(w);zeros_w(w);]; 
    epsT_BNNT(2,:,:) = [zeros_w(w);eps_BNNT(w,'ip',partial);zeros_w(w);]; 
    epsT_BNNT(3,:,:) = [zeros_w(w);zeros_w(w);eps_BNNT(w,'oop',partial);];
    % MoO3 new
    epsT_MoO3 = zeros(3,3,Nw);
    epsT_MoO3(1,:,:) = [eps_MoO3_Full(w,'X');zeros_w(w);zeros_w(w);]; 
    epsT_MoO3(2,:,:) = [zeros_w(w);eps_MoO3_Full(w,'Y');zeros_w(w);]; 
    epsT_MoO3(3,:,:) = [zeros_w(w);zeros_w(w);eps_MoO3_Full(w,'Z');];
    % MoO3: Isotopically enriched O18
    epsT_18O_MoO3 = zeros(3,3,Nw);
    epsT_18O_MoO3(1,:,:) = [eps_MoO3_18O(w,'X');zeros_w(w);zeros_w(w);]; 
    epsT_18O_MoO3(2,:,:) = [zeros_w(w);eps_MoO3_18O(w,'Y');zeros_w(w);]; 
    epsT_18O_MoO3(3,:,:) = [zeros_w(w);zeros_w(w);eps_MoO3_18O(w,'Z');];
    % MoO3: Isotpoically enriched Mo98
    epsT_98Mo_MoO3 = zeros(3,3,Nw);
    epsT_98Mo_MoO3(1,:,:) = [eps_MoO3_98Mo(w,'X');zeros_w(w);zeros_w(w);]; 
    epsT_98Mo_MoO3(2,:,:) = [zeros_w(w);eps_MoO3_98Mo(w,'Y');zeros_w(w);]; 
    epsT_98Mo_MoO3(3,:,:) = [zeros_w(w);zeros_w(w);eps_MoO3_98Mo(w,'Z');];
    % MoO3: Isotpoically enriched Mo98 and 18O
    epsT_98Mo18O_MoO3 = zeros(3,3,Nw);
    epsT_98Mo18O_MoO3(1,:,:) = [eps_MoO3_98Mo18O(w,'X');zeros_w(w);zeros_w(w);]; 
    epsT_98Mo18O_MoO3(2,:,:) = [zeros_w(w);eps_MoO3_98Mo18O(w,'Y');zeros_w(w);]; 
    epsT_98Mo18O_MoO3(3,:,:) = [zeros_w(w);zeros_w(w);eps_MoO3_98Mo18O(w,'Z');];
    % CrSBr new
    epsT_CrSBr = zeros(3,3,Nw);
    epsT_CrSBr(1,:,:) = [eps_CrSBr_spline(w,'X');zeros_w(w);zeros_w(w);]; 
    epsT_CrSBr(2,:,:) = [zeros_w(w);eps_CrSBr_spline(w,'Y');zeros_w(w);]; 
    epsT_CrSBr(3,:,:) = [zeros_w(w);zeros_w(w);eps_CrSBr_spline(w,'Z');];
    % GeS
    epsT_GeS = zeros(3,3,Nw);
    epsT_GeS(1,:,:) = [eps_GeS_exp(w,'X');zeros_w(w);zeros_w(w);]; 
    epsT_GeS(2,:,:) = [zeros_w(w);eps_GeS_exp(w,'Y');zeros_w(w);]; 
    epsT_GeS(3,:,:) = [zeros_w(w);zeros_w(w);eps_GeS_exp(w,'Z');];
    % GeS Test
    epsT_GeSTest = zeros(3,3,Nw);
    epsT_GeSTest(1,:,:) = [eps_GeS_expTest(w,'X');zeros_w(w);zeros_w(w);]; 
    epsT_GeSTest(2,:,:) = [zeros_w(w);eps_GeS_expTest(w,'Y');zeros_w(w);]; 
    epsT_GeSTest(3,:,:) = [zeros_w(w);zeros_w(w);eps_GeS_expTest(w,'Z');];
    % GeS only strong oscillator
    epsT_GeS_st = zeros(3,3,Nw);
    epsT_GeS_st(1,:,:) = [eps_GeS_exp_st(w,'X');zeros_w(w);zeros_w(w);]; 
    epsT_GeS_st(2,:,:) = [zeros_w(w);eps_GeS_exp_st(w,'Y');zeros_w(w);]; 
    epsT_GeS_st(3,:,:) = [zeros_w(w);zeros_w(w);eps_GeS_exp_st(w,'Z');];
    % GeS only weak oscillator
    epsT_GeS_we = zeros(3,3,Nw);
    epsT_GeS_we(1,:,:) = [eps_GeS_exp_we(w,'X');zeros_w(w);zeros_w(w);]; 
