    epsT_GeS_allZ_stststwe(2,:,:) = [zeros_w(w);eps_GeS_exp_allZ_stststwe(w,'Y');zeros_w(w);]; 
    epsT_GeS_allZ_stststwe(3,:,:) = [zeros_w(w);zeros_w(w);eps_GeS_exp_allZ_stststwe(w,'Z');];
            % GeS only weak oscillator
    epsT_GeS_allZ_stwestwestwe = zeros(3,3,Nw);
    epsT_GeS_allZ_stwestwestwe(1,:,:) = [eps_GeS_exp_allZ_stwestwestwe(w,'X');zeros_w(w);zeros_w(w);]; 
    epsT_GeS_allZ_stwestwestwe(2,:,:) = [zeros_w(w);eps_GeS_exp_allZ_stwestwestwe(w,'Y');zeros_w(w);]; 
    epsT_GeS_allZ_stwestwestwe(3,:,:) = [zeros_w(w);zeros_w(w);eps_GeS_exp_allZ_stwestwestwe(w,'Z');];
                % GeS only weak oscillator
    epsT_GeS_allZ_stwestst = zeros(3,3,Nw);
    epsT_GeS_allZ_stwestst(1,:,:) = [eps_GeS_exp_allZ_stwestst(w,'X');zeros_w(w);zeros_w(w);]; 
    epsT_GeS_allZ_stwestst(2,:,:) = [zeros_w(w);eps_GeS_exp_allZ_stwestst(w,'Y');zeros_w(w);]; 
    epsT_GeS_allZ_stwestst(3,:,:) = [zeros_w(w);zeros_w(w);eps_GeS_exp_allZ_stwestst(w,'Z');];
                % GeS only weak oscillator
    epsT_GeS_allZ_ststwest = zeros(3,3,Nw);
    epsT_GeS_allZ_ststwest(1,:,:) = [eps_GeS_exp_allZ_ststwest(w,'X');zeros_w(w);zeros_w(w);]; 
    epsT_GeS_allZ_ststwest(2,:,:) = [zeros_w(w);eps_GeS_exp_allZ_ststwest(w,'Y');zeros_w(w);]; 
    epsT_GeS_allZ_ststwest(3,:,:) = [zeros_w(w);zeros_w(w);eps_GeS_exp_allZ_ststwest(w,'Z');];
                    % GeS only weak oscillator
    epsT_GeS_allZ_wewewe = zeros(3,3,Nw);
    epsT_GeS_allZ_wewewe(1,:,:) = [eps_GeS_exp_allZ_wewewe(w,'X');zeros_w(w);zeros_w(w);]; 
    epsT_GeS_allZ_wewewe(2,:,:) = [zeros_w(w);eps_GeS_exp_allZ_wewewe(w,'Y');zeros_w(w);]; 
    epsT_GeS_allZ_wewewe(3,:,:) = [zeros_w(w);zeros_w(w);eps_GeS_exp_allZ_wewewe(w,'Z');];
%     epsT_GeS(1,:,:) = [-22.3349 + 5.0016i;zeros_w(w);zeros_w(w);]; 
%     epsT_GeS(2,:,:) = [zeros_w(w);2.1017 + 0.4425i;zeros_w(w);]; 
%     epsT_GeS(3,:,:) = [zeros_w(w);zeros_w(w);-12.1186 + 11.4996i;];
%     % ARBITRARY MATERIAL
%     epsT_Newmat = zeros(3,3,Nw);
%     epsT_Newmat(1,:,:) = [eps_Newmat(w,'X');zeros_w(w);zeros_w(w);]; 
%     epsT_Newmat(2,:,:) = [zeros_w(w);eps_Newmat(w,'Y');zeros_w(w);]; 
%     epsT_Newmat(3,:,:) = [zeros_w(w);zeros_w(w);eps_Newmat(w,'Z');];
    % HfSe
    epsT_HfSe = zeros(3,3,Nw);
    epsT_HfSe(1,:,:) = [eps_HfSe_exp(w,'X');zeros_w(w);zeros_w(w);]; 
    epsT_HfSe(2,:,:) = [zeros_w(w);eps_HfSe_exp(w,'Y');zeros_w(w);]; 
    epsT_HfSe(3,:,:) = [zeros_w(w);zeros_w(w);eps_HfSe_exp(w,'Z');];
        % ScN A
    epsT_ScN_A = zeros(3,3,Nw);
    epsT_ScN_A(1,:,:) = [eps_ScN_A(w);zeros_w(w);zeros_w(w);]; 
    epsT_ScN_A(2,:,:) = [zeros_w(w);eps_ScN_A(w);zeros_w(w);]; 
    epsT_ScN_A(3,:,:) = [zeros_w(w);zeros_w(w);eps_ScN_A(w);];
            % MgO
    epsT_MgO = zeros(3,3,Nw);
    epsT_MgO(1,:,:) = [eps_MgO_exp(w);zeros_w(w);zeros_w(w);]; 
    epsT_MgO(2,:,:) = [zeros_w(w);eps_MgO_exp(w);zeros_w(w);]; 
    epsT_MgO(3,:,:) = [zeros_w(w);zeros_w(w);eps_MgO_exp(w);];
    % 6H-SiC without weak modes
    epsT_SiC = zeros(3,3,Nw);
    epsT_SiC(1,:,:) = [eps_SiCx(w);zeros_w(w);zeros_w(w);]; 
    epsT_SiC(2,:,:) = [zeros_w(w);eps_SiCx(w);zeros_w(w);]; 
    epsT_SiC(3,:,:) = [zeros_w(w);zeros_w(w);eps_SiCz(w);];     
    % 4H-SiC
    epsT_SiC4H = zeros(3,3,Nw);
    epsT_SiC4H(1,:,:) = [eps_SiC4Hx(w);zeros_w(w);zeros_w(w);]; 
    epsT_SiC4H(2,:,:) = [zeros_w(w);eps_SiC4Hx(w);zeros_w(w);]; 
    epsT_SiC4H(3,:,:) = [zeros_w(w);zeros_w(w);eps_SiC4Hz(w);];         
    % 6H-SiC
    epsT_SiC6H = zeros(3,3,Nw);
    epsT_SiC6H(1,:,:) = [eps_SiC6Hx(w);zeros_w(w);zeros_w(w);]; 
    epsT_SiC6H(2,:,:) = [zeros_w(w);eps_SiC6Hx(w);zeros_w(w);]; 
    epsT_SiC6H(3,:,:) = [zeros_w(w);zeros_w(w);eps_SiC6Hz(w);];                
    % GaAs
    epsT_GaAs = zeros(3,3,Nw);
    epsT_GaAs(1,:,:) = [eps_GaAs(w);zeros_w(w);zeros_w(w);]; 
    epsT_GaAs(2,:,:) = [zeros_w(w);eps_GaAs(w);zeros_w(w);]; 
    epsT_GaAs(3,:,:) = [zeros_w(w);zeros_w(w);eps_GaAs(w);];        
    % InAs
    epsT_InAs = zeros(3,3,Nw);
    epsT_InAs(1,:,:) = [eps_InAs(w);zeros_w(w);zeros_w(w);]; 
    epsT_InAs(2,:,:) = [zeros_w(w);eps_InAs(w);zeros_w(w);]; 
    epsT_InAs(3,:,:) = [zeros_w(w);zeros_w(w);eps_InAs(w);];    
    % GaP
    epsT_GaP = zeros(3,3,Nw);
    epsT_GaP(1,:,:) = [eps_GaP(w);zeros_w(w);zeros_w(w);]; 
    epsT_GaP(2,:,:) = [zeros_w(w);eps_GaP(w);zeros_w(w);]; 
    epsT_GaP(3,:,:) = [zeros_w(w);zeros_w(w);eps_GaP(w);];              
    %collect epsilon tensors for all layers
    for kl = 1:Nds
        switch mats{kl}
            case 'vac'                         
                epsTarray{kl} = epsT_vac;
            case 'air'                         
                epsTarray{kl} = epsT_vac;
            case 'KRS5'
                epsTarray{kl} = epsT_KRS5;
            case 'Au'
                epsTarray{kl} = epsT_Au;
            case 'AuEff'
                epsTarray{kl} = epsT_Au_eff;
            case 'MetaAuA'
                epsTarray{kl} = epsT_MetaAuA;
            case 'MetaAuB'
                epsTarray{kl} = epsT_MetaAuB;
            case 'MetaAuC'
                epsTarray{kl} = epsT_MetaAuC;
            case 'MetaAuD'
                epsTarray{kl} = epsT_MetaAuD;
            case 'MetaP4'
                epsTarray{kl} = epsT_MetaP4;
            case 'MetaP5'
                epsTarray{kl} = epsT_MetaP5;
            % case 'Ag'
            %     epsTarray{kl} = epsT_Ag;
            case 'Si'
                epsTarray{kl} = epsT_Si;
            case 'SiHRFZ'
                epsTarray{kl} = epsT_SiHRFZ;
            case 'effSub'
                epsTarray{kl} = epsT_effSub;
            case 'Ge'
                epsTarray{kl} = epsT_Ge;
            case 'Diamond'
                epsTarray{kl} = epsT_Diamond;    
            case 'MgO'
                epsTarray{kl} = epsT_MgO;
            case 'SiC4H'
                epsTarray{kl} = epsT_SiC4H;
            case 'SiC6H'
                epsTarray{kl} = epsT_SiC6H;
            case 'SiC'                     % 6H-SiC without weak modes
                epsTarray{kl} = epsT_SiC;
            case 'STO'
                epsTarray{kl} = epsT_STO;
            case 'AlN'
                epsTarray{kl} = epsT_AlN;
            case 'GaN'
                epsTarray{kl} = epsT_GaN;
            case 'ScN_A'
                epsTarray{kl} = epsT_ScN_A;
            case 'InN'
                epsTarray{kl} = epsT_InN;
            case 'hBN'
                epsTarray{kl} = epsT_hBN;
            case 'BNNT'
                epsTarray{kl} = epsT_BNNT;
            case 'SiO2'                    % alpha quartz
                epsTarray{kl} = epsT_SiO2;
            case 'Al2O3'                    % alumina
                epsTarray{kl} = epsT_Al2O3;      
            case 'BaTiO3'                    % perovskite Barium titanate
                epsTarray{kl} = epsT_BaTiO3;                      
            case 'MoO3'                    % MoO3
                epsTarray{kl} = epsT_MoO3;    
            case '18O-MoO3' % 5% redshift from Ryan PSU  180 isotopically enriched MoO3
                epsTarray{kl} = epsT_18O_MoO3;
            case '98Mo-MoO3' % % redshift from Ryan PSU   98Mo isotopically enriched MoO3
                epsTarray{kl} = epsT_98Mo_MoO3; 
            case '98Mo18O-MoO3' % %
                epsTarray{kl} = epsT_98Mo18O_MoO3;  
            case 'CrSBr'                    % MoO3
                epsTarray{kl} = epsT_CrSBr;  
            case 'Newmat'                   % ARBITRARY MATERIAL
                epsTarray{kl} = epsT_Newmat;
            case 'Newsub'                   % ARBITRARY MATERIAL
                epsTarray{kl} = epsT_Newsub;
            case 'GeS'                   % GeS
                epsTarray{kl} = epsT_GeS;
            case 'GeSTest'                   % GeS
                epsTarray{kl} = epsT_GeSTest;
            case 'GeSwe'                   % GeS
                epsTarray{kl} = epsT_GeS_we;
            case 'GeSst'                   % GeS 
                epsTarray{kl} = epsT_GeS_st;
            case 'GeS_allZ_ststst'         % GeS, all directions like z, only strong phonon
                epsTarray{kl} = epsT_GeS_allZ_ststst;
            case 'GeS_allZ_stwestwest'         % GeS, all directions like z, only strong phonon out-of-plane
                epsTarray{kl} = epsT_GeS_allZ_stwestwest;
            case 'GeS_allZ_stststwe'         % GeS, all directions like z, only strong phonon in-plane
                epsTarray{kl} = epsT_GeS_allZ_stststwe;
            case 'GeS_allZ_stwestwestwe'         % GeS, all directions like z, only strong phonon out-of-plane
                epsTarray{kl} = epsT_GeS_allZ_stwestwestwe;
            case 'GeS_allZ_stwestst'         % GeS, all directions like z, only strong phonon out-of-plane
                epsTarray{kl} = epsT_GeS_allZ_stwestst;
            case 'GeS_allZ_ststwest'         % GeS, all directions like z, only strong phonon out-of-plane
                epsTarray{kl} = epsT_GeS_allZ_ststwest;
            case 'GeS_allZ_wewewe'         % GeS, all directions like z, only strong phonon out-of-plane
                epsTarray{kl} = epsT_GeS_allZ_wewewe;
            case 'GaAs'                     %GaAs
                epsTarray{kl} = epsT_GaAs;
            case 'GaP'                     %GaP
                epsTarray{kl} = epsT_GaP;                
            case 'InAs'                     %InAs
                epsTarray{kl} = epsT_InAs;                
            case 'CaF2'                      % n data from Li (1980), valid for 0.15-12µm
                epsTarray{kl} = epsT_CaF2;             
            case 'BaF2'                      % tabulated BaF2 from Tom Folland
                epsTarray{kl} = epsT_BaF2;    
            case 'HfSe'                      % from Alex Paarmann
                epsTarray{kl} = epsT_HfSe; 
            case 'bGO'                      % from Alex Paarmann
                epsTarray{kl} = eps_bGa2O3(w); 
            otherwise
                fprintf('material #%d unknown.\n',kl)
                epsTarray = [];
                return
        end
        % add drude contribution in case of doping 
        if any(doping{kl}(1))
            drude = zeros(1,1,Nw);
            wp = doping{kl}(1); Gp = doping{kl}(2);
            drude(1,1,:) = epsilon_drude(w,wp,Gp);
            for kk=1:3
                epsTarray{kl}(kk,kk,:) = epsTarray{kl}(kk,kk,:) + drude;
            end
        end
        % rotate coordinate system if euler angles are finite
        if any(euler{kl})
            epsTl = epsTarray{kl};
            epsTarray{kl} = euler_transform(epsTl,euler{kl});
        end
    end
end

