function eps = epsilon_drude(w,wp,Gp)
    eps = 1 - wp^2./(w.^2+1i*Gp*w);
end

function eps = epsilon_1phonon(w,wT,wL,gT,gL,epsinf)
    eps  = epsinf*(w.^2-wL^2+1i*gL*w)./(w.^2-wT^2+1i*gT*w);
end

function eps = epsilon_3phonon(w,wT,wL,gT,gL,wTw1,wLw1,wTw2,wLw2,gTw,epsinf)
    eps  = epsinf*(1+(wT.^2-wL^2)./(w.^2-wT^2+1i*gT*w)+(wTw1.^2-wLw1^2)./(w.^2-wTw1^2+1i*gTw*w)+(wTw2.^2-wLw2^2)./(w.^2-wTw2^2+1i*gTw*w));
end

function epsTout = euler_transform(epsT,euler)
    % euler matrix
    %
    Nw = size(epsT,3);
    epsTout = zeros(3,3,Nw);
    epsTl = zeros(3,3);
    D = euler_matrix(euler);
    for kw = 1:Nw
        epsTl(:,:) = epsT(:,:,kw); 
        epsTout(:,:,kw) = transpose(D)*epsTl*D;
    end
end
% euler matrix as defined in wikipedia, 'z,x',z'''
% first rotation (alpha) about the z-axis
% second rotation (beta) about the 'new' x-axis'
% last rotation (gamma) again about the z-axis
function D = euler_matrix(euler_angles)
    al = euler_angles(1);
    be = euler_angles(2);
    ga = euler_angles(3);
    D = zeros(3,3);
    D(1,1) =  cos(al)*cos(ga) - sin(al)*cos(be)*sin(ga);
    D(2,2) = -sin(al)*sin(ga) + cos(al)*cos(be)*cos(ga);
    D(3,3) =  cos(be);
    D(1,2) = -cos(al)*sin(ga) - sin(al)*cos(be)*cos(ga);
    D(2,1) =  sin(al)*cos(ga) + cos(al)*cos(be)*sin(ga);
    D(1,3) =  sin(al)*sin(be);
    D(2,3) = -cos(al)*sin(be);
    D(3,1) =  sin(be)*sin(ga);
    D(3,2) =  sin(be)*cos(ga);
end

function b = convert_photon_units(a,IN,OUT)
    c = 2.997e8;
    d = 1.23984193;
    %convert to um
    switch IN
        case 'um'
            um = a;
        case 'wn'
            um = 1./a*1e4;
        case 'THz'
            um = c./a*1e-6;
        case 'eV'
            um = d./a;
        case 'nm'
            um = a*1e-3;
    end
    %convert to out unit
    switch OUT
        case 'um'
            b = um;
        case 'wn'
            b = 1./um*1e4;
        case 'THz'
            b = c./um*1e-6;
        case 'eV'
            b = d./um;
        case 'nm'
            b = um*1e3;
    end
end